using System.Diagnostics;
using System.Net;
using System.Net.Http.Json;
using System.Net.Sockets;
using System.Text.Json;
using Lmu.Manager;
using Lmu.Web;
using Lmu.SetupLibrary;

static class HomeNetworkTests
{
 public static async Task Child(string[] args)
 {
  var store=new SettingsStore(args[1]);var nets=new Networks{Foreign=args[3]=="foreign"};string token=(await Console.In.ReadLineAsync())??"";
  await using var manager=new ManagerController(store,args[2],nets,new Auto());await manager.StartAsync();
  if(args[3]=="disable"){manager.RequestHomeNetwork(new(false));await Settled(manager);}
  using var client=new HttpClient(new HttpClientHandler{UseProxy=false,UseCookies=false}){BaseAddress=new("http://127.0.0.1:"+manager.View().Settings.Port)};client.DefaultRequestHeaders.Add("Cookie","lmu-library-access="+token);
  var session=await client.GetFromJsonAsync<JsonElement>("/api/session");var view=manager.View();
  Console.WriteLine(JsonSerializer.Serialize(new{SavedEnabled=store.Load().LanEnabled,HasApproval=store.Load().Network is not null,view.LanActive,DeviceCount=view.Devices.Length,Authenticated=manager.AuthenticateDevice(token),HttpAuthenticated=session.GetProperty("authenticated").GetBoolean(),PortClosed=PortClosed(view.Settings.Port),view.NetworkSetup!.State}));
 }
 private static bool PortClosed(int port){var listener=new TcpListener(IPAddress.Parse("127.0.0.2"),port);try{listener.Start();return true;}catch(SocketException){return false;}finally{listener.Stop();}}
 private static async Task Settled(ManagerController manager){var until=DateTimeOffset.UtcNow.AddSeconds(15);while(manager.View().Changing&&DateTimeOffset.UtcNow<until)await Task.Delay(30);if(manager.View().Changing)throw new Exception("Synthetic settings timeout");}
 public static async Task Run(Action<bool,string> check)
 {
  var root=Path.GetFullPath(Path.Combine("artifacts","home10-tests-"+Guid.NewGuid().ToString("N")));var store=new SettingsStore(Path.Combine(root,"settings"));var db=Path.Combine(root,"library.sqlite");var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();store.Save(new(false,false,port,TrayLanguage:"de"));var nets=new Networks();var network=nets.Read()[0];ManagerController? manager=new(store,db,nets,new Auto());string token="";
  HttpClient Owner(){var c=new HttpClient(new HttpClientHandler{UseProxy=false,UseCookies=false}){BaseAddress=new("http://127.0.0.1:"+port)};c.DefaultRequestHeaders.Authorization=new("Bearer",new Uri(manager!.LocalUrl()).Fragment.Split("access=")[1].Split('&')[0]);return c;}
  async Task<HttpStatusCode> Change(HttpClient owner,HomeNetworkRequest request){var response=await owner.PostAsJsonAsync("/api/manager/home-network",request);if(response.StatusCode==HttpStatusCode.Accepted)await Settled(manager!);return response.StatusCode;}
  async Task<JsonElement> Restart(string mode){var info=new ProcessStartInfo{FileName=Path.Combine(AppContext.BaseDirectory,"Lmu.B25.Tests.exe"),UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in new[]{"--home-process",store.DirectoryPath,db,mode})info.ArgumentList.Add(a);using var process=Process.Start(info)!;var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();await process.StandardInput.WriteLineAsync(token);process.StandardInput.Close();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(20));try{await process.WaitForExitAsync(timeout.Token);}catch{process.Kill(true);throw;}check(process.ExitCode==0&&(await error).Length==0,"real isolated child process exits without errors: "+mode);return JsonSerializer.Deserialize<JsonElement>(await output);}
  try{
   await manager.StartAsync();check(!manager.View().LanActive&&PortClosed(port),"first startup exposes no LAN listener before approval");
   using var owner=Owner();var session=await owner.GetFromJsonAsync<JsonElement>("/api/session");owner.DefaultRequestHeaders.Add("X-LMU-CSRF",session.GetProperty("csrf").GetString());
   using(var anonymous=new HttpClient{BaseAddress=owner.BaseAddress})check((await anonymous.PostAsJsonAsync("/api/manager/home-network",new HomeNetworkRequest(true,network.Fingerprint,true))).StatusCode==HttpStatusCode.Unauthorized,"new home action requires authentication");
   using(var noCsrf=Owner())check((await noCsrf.PostAsJsonAsync("/api/manager/home-network",new HomeNetworkRequest(true,network.Fingerprint,true))).StatusCode==HttpStatusCode.Forbidden,"new home action requires CSRF");
   check((await owner.PostAsJsonAsync("/api/manager/preferences",new{OpenBrowser=false,AutoStart=false,Port=port,LanEnabled=true})).StatusCode==HttpStatusCode.BadRequest,"preferences reject a hidden network-access mutation");
   check(await Change(owner,new(true,network.Fingerprint))==HttpStatusCode.BadRequest,"initial access requires explicit single consent");check(await Change(owner,new(true,"STALE",true))==HttpStatusCode.BadRequest,"consent cannot approve stale or invented network identity");
   check(await Change(owner,new(true,network.Fingerprint,true))==HttpStatusCode.Accepted&&manager.View().LanActive,"one informed consent activates exactly selected eligible connection");
   check(store.Load().LanEnabled&&store.Load().Network is{Trusted:true,HttpRiskAccepted:true,FirewallUnderstood:true}&&store.Load().Network!.Fingerprint==network.Fingerprint,"one consent persists complete approval and user switch");
   var invitation=JsonSerializer.SerializeToElement(manager.Invite("SYNTHETIC retained tablet"));string once=invitation.GetProperty("Urls")[0].GetString()!.Split("access=")[1];using(var pair=new HttpClient{BaseAddress=owner.BaseAddress}){var response=await pair.PostAsJsonAsync("/api/session",new{key=once});token=response.Headers.GetValues("Set-Cookie").Single().Split(';')[0].Split('=')[1];}
   check(manager.View().Devices.Length==1&&manager.AuthenticateDevice(token),"paired tablet is protected and authorized");var grantBytes=File.ReadAllBytes(Path.Combine(store.DirectoryPath,"devices.protected"));
   check(await Change(owner,new(false))==HttpStatusCode.Accepted&&!manager.View().LanActive&&PortClosed(port),"main switch off closes LAN listening address");check(!store.Load().LanEnabled&&store.Load().Network is not null&&manager.View().Devices.Length==1,"off retains approval and device independently");
   check(await Change(owner,new(true))==HttpStatusCode.Accepted&&manager.AuthenticateDevice(token),"same approved home resumes without new consent or pairing");
   var before=File.ReadAllBytes(Path.Combine(store.DirectoryPath,"settings.json"));nets.Foreign=true;check(!manager.View().LanActive&&!manager.AuthenticateDevice(token),"foreign identity blocks access before asynchronous cleanup");await manager.CheckNetworkAsync();check(PortClosed(port)&&store.Load().LanEnabled&&store.Load().Network?.Fingerprint==network.Fingerprint,"recognized foreign network suspends listener without erasing saved request");check(File.ReadAllBytes(Path.Combine(store.DirectoryPath,"settings.json")).SequenceEqual(before),"runtime validation failure never rewrites saved approval");
   nets.Foreign=false;await manager.CheckNetworkAsync();check(manager.View().LanActive&&manager.AuthenticateDevice(token),"return to exact approved fingerprint automatically restores access");
   nets.Available=false;await manager.CheckNetworkAsync();check(!manager.View().LanActive&&manager.View().NetworkSetup!.State=="unavailable"&&store.Load().LanEnabled,"discovery failure is separate from user off");nets.Available=true;await manager.CheckNetworkAsync();check(manager.AuthenticateDevice(token),"return after discovery failure needs no new invitation");
   check(await Change(owner,new(false,RemoveApproval:true))==HttpStatusCode.BadRequest,"approval removal requires its own confirmation");check(await Change(owner,new(false,Confirmed:true,RemoveApproval:true))==HttpStatusCode.Accepted&&store.Load().Network is null&&!store.Load().LanEnabled&&PortClosed(port),"confirmed removal deletes only network approval and closes access");check(manager.View().Devices.Length==1,"network approval removal never deletes paired devices");check(await Change(owner,new(true))==HttpStatusCode.BadRequest,"removed approval cannot be reused by switch alone");
   check(await Change(owner,new(true,network.Fingerprint,true))==HttpStatusCode.Accepted&&manager.AuthenticateDevice(token),"one fresh network consent restores existing tablet authorization");
   using(var device=new HttpClient{BaseAddress=owner.BaseAddress}){device.DefaultRequestHeaders.Add("Cookie","lmu-library-access="+token);device.DefaultRequestHeaders.Add("X-LMU-CSRF",session.GetProperty("csrf").GetString());check((await device.PostAsJsonAsync("/api/manager/home-network",new HomeNetworkRequest(false))).StatusCode==HttpStatusCode.Forbidden,"paired device cannot change owner network access");check((await device.PostAsJsonAsync("/api/manager/preferences",new ManagerPreferences(false,false,port))).StatusCode==HttpStatusCode.Forbidden,"paired device cannot change owner preferences");}
   using(var foreign=Owner()){foreign.DefaultRequestHeaders.Add("X-LMU-CSRF",session.GetProperty("csrf").GetString());foreign.DefaultRequestHeaders.Add("Origin","http://foreign.example");check((await foreign.PostAsJsonAsync("/api/manager/home-network",new HomeNetworkRequest(false))).StatusCode==HttpStatusCode.Forbidden,"home action retains same-origin protection");}
   var pendingInvite=JsonSerializer.SerializeToElement(manager.Invite("SYNTHETIC pending while language changes"));await owner.PostAsJsonAsync("/api/manager/preferences",new ManagerPreferences(false,false,port,"en"));await Settled(manager);check(manager.InvitationStatus(pendingInvite.GetProperty("Id").GetGuid()).Status=="active","language preferences do not invalidate a pending invitation");
   nets.Foreign=true;await manager.CheckNetworkAsync();var preferences=await owner.PostAsJsonAsync("/api/manager/preferences",new ManagerPreferences(false,false,port,"en"));await Settled(manager);check(preferences.StatusCode==HttpStatusCode.Accepted&&store.Load().LanEnabled&&store.Load().Network is not null&&store.Load().TrayLanguage=="en","unrelated preferences cannot turn paused network intent off");nets.Foreign=false;await manager.CheckNetworkAsync();
   await manager.DisposeAsync();manager=null;
   for(int i=0;i<2;i++){var child=await Restart("normal");check(child.GetProperty("LanActive").GetBoolean()&&child.GetProperty("HttpAuthenticated").GetBoolean()&&child.GetProperty("DeviceCount").GetInt32()==1,"full process restart restores LAN and persistent HTTP cookie "+i);}
   var changed=await Restart("foreign");check(changed.GetProperty("SavedEnabled").GetBoolean()&&changed.GetProperty("HasApproval").GetBoolean()&&!changed.GetProperty("LanActive").GetBoolean()&&changed.GetProperty("PortClosed").GetBoolean(),"foreign network at full startup opens no LAN listener and preserves approval");
   var returned=await Restart("normal");check(returned.GetProperty("LanActive").GetBoolean()&&returned.GetProperty("Authenticated").GetBoolean(),"process restart returning home recovers saved tablet without confirmation");
   await Restart("disable");var off=await Restart("normal");check(!off.GetProperty("SavedEnabled").GetBoolean()&&!off.GetProperty("LanActive").GetBoolean()&&off.GetProperty("HasApproval").GetBoolean()&&off.GetProperty("DeviceCount").GetInt32()==1,"deliberate off survives a complete process restart without forgetting approval/devices");
   check(File.ReadAllBytes(Path.Combine(store.DirectoryPath,"devices.protected")).SequenceEqual(grantBytes),"all network actions and subprocess restarts preserve exact protected device bytes");
   manager=new(store,db,nets,new Auto());await manager.StartAsync();manager.RequestHomeNetwork(new(true));await Settled(manager);await manager.DisposeAsync();manager=null;
   var busy=new TcpListener(IPAddress.Parse("127.0.0.2"),port);busy.Start();try{manager=new(store,db,nets,new Auto());await manager.StartAsync();check(!manager.View().LanActive&&store.Load().LanEnabled&&store.Load().Network is not null&&manager.View().Devices.Length==1,"startup LAN bind failure retains persistent request approval and tablet");check(manager.View().NetworkSetup!.State=="listener-unavailable","bind failure is reported separately from network mismatch or user off");}finally{busy.Stop();}
   await Task.Delay(5200);await manager!.CheckNetworkAsync();check(manager.View().LanActive&&manager.AuthenticateDevice(token),"bounded listener retry recovers original approval without another consent");
   var settingsFile=Path.Combine(store.DirectoryPath,"settings.json");File.SetAttributes(settingsFile,FileAttributes.ReadOnly);try{manager.RequestHomeNetwork(new(false));await Settled(manager);check(!manager.View().LanActive&&PortClosed(port)&&manager.View().NetworkSetup!.State=="save-failed"&&store.Load().LanEnabled,"failed off persistence closes LAN and reports failure without claiming saved off");await manager.CheckNetworkAsync();check(!manager.View().LanActive,"persistence failure cannot silently reactivate listener");}finally{File.SetAttributes(settingsFile,FileAttributes.Normal);}
   manager.RequestHomeNetwork(new(false));await Settled(manager);check(!store.Load().LanEnabled&&manager.View().Devices.Length==1,"explicit off after storage recovery persists without losing tablet");manager.RequestHomeNetwork(new(true));await Settled(manager);manager.Revoke(manager.View().Devices.Single().Id);check(!manager.AuthenticateDevice(token)&&manager.View().Settings.Network is not null&&manager.View().LanActive,"individual device revocation leaves network approval and listener unchanged");
   check(store.Load().TrayLanguage=="en"&&!store.Load().OpenBrowser,"other preferences survive all network transitions");
  }finally{if(manager is not null)await manager.DisposeAsync();}
 }
 private sealed class Networks:IPrivateNetworks{public bool Available=true,Foreign;public PrivateInterface[] Read()=>Available?[new("SYNTHETIC-HOME",IPAddress.Parse("127.0.0.2"),8,"SYNTHETIC Ethernet",Foreign?"22222222-2222-2222-2222-222222222222":"11111111-1111-1111-1111-111111111111",0,"127.0.0.1","SYNTHETIC physical MAC","Ethernet",true)]:[];}
 private sealed class Auto:IAutoStart{public bool Enabled=>false;public void Set(bool enabled){}}
}
